class S:
 def __len__(self):
  print("len")
  return 3
 def __getitem__(self,i):
  print("get",i)
  return i+10
print([x for x in reversed(S())])

class S:
 def __len__(self):
  print("len")
  return 3
 def __getitem__(self,i):
  print("get",i)
  return i+10
i=reversed(S())
S.__len__=lambda self:0
print(next(i),next(i),next(i),next(i,99))

