class S:
 def __len__(self):
  print("len")
  return 3
 def __getitem__(self,i):
  print("get",i)
  return i+10
S.__reversed__=lambda self:iter([7,8])
print(list(reversed(S())))

class S:
 @staticmethod
 def __reversed__(): return iter([5])
print(list(reversed(S())))

class S:
 @classmethod
 def __reversed__(cls): return cls.__name__
print(reversed(S()))

class D:
 def __get__(self,obj,owner):
  print("bind",owner.__name__)
  return lambda:iter([6])
class S: __reversed__=D()
print(list(reversed(S())))

class D:
 def __get__(self,obj,owner): raise AttributeError("binding")
class S:
 __reversed__=D()
 def __len__(self): print("wrong");return 0
 def __getitem__(self,i): return i
reversed(S())

class S:
 def __len__(self): return 2
 def __getitem__(self,i): print("get",i);raise IndexError("bad")
i=reversed(S())
try: print(next(i,99))
except IndexError as e: print(str(e))
S.__getitem__=lambda self,i:i
print(next(i,99))

class S:
 def __len__(self): return 2
 def __getitem__(self,i): print("get",i);raise StopIteration("bad")
i=reversed(S())
try: print(next(i,99))
except StopIteration as e: print(str(e))
S.__getitem__=lambda self,i:i
print(next(i,99))

class S:
